The source order interleaves independent workgroup tapes; it is not a memory
order between them.  An event wait orders the named operation's completion,
while a barrier or commit completes all earlier operations in its scope.
"""

from __future__ import annotations

from collections import deque
from collections.abc import Callable, Iterable
from dataclasses import dataclass
from math import gcd

from .isa import Instruction, iter_parse
from .pipeline_events import ProgramQueues, group_program


@dataclass(frozen=True)
class _Knowledge:
    prefixes: dict[int, int]
    events: frozenset[tuple[int, int]]

    def contains(self, identity: tuple[int, int]) -> bool:
        tape, number = identity
        return self.prefixes.get(tape, 0) >= number or identity in self.events


_EMPTY = _Knowledge({}, frozenset())


def _join(*items: _Knowledge) -> _Knowledge:
    prefixes: dict[int, int] = {}
    events: set[tuple[int, int]] = set()
    for item in items:
        for tape, number in item.prefixes.items():
            prefixes[tape] = max(prefixes.get(tape, 0), number)
        events.update(item.events)
    return _Knowledge(prefixes, frozenset(events))


def _completed(knowledge: _Knowledge, tape: int, number: int) -> _Knowledge:
    return _join(knowledge, _Knowledge({tape: number}, frozenset()))


def _event(knowledge: _Knowledge, identity: tuple[int, int]) -> _Knowledge:
    return _join(knowledge, _Knowledge({}, frozenset({identity})))


def _bounds(desc: dict) -> tuple[int, int]:
    shape = desc.get("shape", [desc["count"]])
    strides = desc.get("strides", [1])
    return desc["offset"], desc["offset"] + 1 + sum(
        (extent - 1) * stride for extent, stride in zip(shape, strides)
    )


def _positions(desc: dict):
    offset = desc["offset"]
    shape = desc.get("shape", [desc["count"]])
    strides = desc.get("strides", [1])
    if len(shape) == 1:
        for index in range(shape[0]):
            yield offset + index * strides[0]
    else:
        for row in range(shape[0]):
            for col in range(shape[1]):
                yield offset + row * strides[0] + col * strides[1]


def _contains_position(desc: dict, position: int) -> bool:
    delta = position - desc["offset"]
    shape = desc.get("shape", [desc["count"]])
    strides = desc.get("strides", [1])
    if len(shape) == 1:
        return delta >= 0 and delta % strides[0] == 0 and delta // strides[0] < shape[0]
    # Iterate the smaller dimension; the other dimension is tested arithmetically.
    first = 0 if shape[0] <= shape[1] else 1
    second = 1 - first
    for index in range(shape[first]):
        rest = delta - index * strides[first]
        if rest >= 0 and rest % strides[second] == 0 and rest // strides[second] < shape[second]:
            return True
    return False


def _contiguous(desc: dict) -> bool:
    shape = desc.get("shape", [desc["count"]])
    strides = desc.get("strides", [1])
    if len(shape) == 1:
        return strides[0] == 1
    return (strides[1] == 1 and strides[0] == shape[1]) or (
        strides[0] == 1 and strides[1] == shape[0]
    )


def _overlap(left: dict, right: dict) -> bool:
    lo, hi = _bounds(left)
    other_lo, other_hi = _bounds(right)
    if lo >= other_hi or other_lo >= hi:
        return False
    left_shape = left.get("shape", [left["count"]])
    right_shape = right.get("shape", [right["count"]])
    left_strides = left.get("strides", [1])
    right_strides = right.get("strides", [1])
    left_contiguous = _contiguous(left)
    right_contiguous = _contiguous(right)
    if left_contiguous and right_contiguous:
        return True
    if len(left_shape) == len(right_shape) == 1:
        # A cheap rejection for interleaved one-dimensional views.
        if (left["offset"] - right["offset"]) % gcd(left_strides[0], right_strides[0]):
            return False
    smaller, larger = (left, right) if left["count"] <= right["count"] else (right, left)
    if _contiguous(larger):
        large_lo, large_hi = _bounds(larger)
        return any(large_lo <= position < large_hi for position in _positions(smaller))
    if smaller["count"] <= 64 or len(larger.get("shape", [larger["count"]])) == 1:
        return any(_contains_position(larger, position) for position in _positions(smaller))
    positions = set(_positions(smaller))

